/** Official mobile website in the foreground only. Downloads use the separate existing analyzer. */
@androidx.media3.common.util.UnstableApi
public class YouTubeActivity extends Activity {
 private LinearLayout holder;private TextView status;private Button formats,favorite,favorites;private AlertDialog saveDialog;private WebView web;private EditText query;private Button voice;private boolean recognizing;private volatile boolean protectionEnabled;private final java.util.concurrent.atomic.AtomicInteger blocked=new java.util.concurrent.atomic.AtomicInteger();
 private String lastUrl="https://m.youtube.com/",pendingUrl="";private boolean visible;
 static boolean allowed(String raw){try{java.net.URI uri=new java.net.URI(raw);return raw.length()<=4096&&"https".equalsIgnoreCase(uri.getScheme())&&uri.getUserInfo()==null&&uri.getPort()==-1&&MediaLinks.isYoutube(raw);}catch(Exception e){return false;}}
 static String searchUrl(String phrase){String clean=phrase==null?"":phrase.trim();if(clean.isEmpty()||clean.length()>160)return "";return Uri.parse("https://m.youtube.com/results").buildUpon().appendQueryParameter("search_query",clean).build().toString();}
 private void search(){String url=searchUrl(query.getText().toString());if(url.isEmpty()){status.setText("Diga ou digite o nome de uma música ou artista, até 160 caracteres.");return;}((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);load(url);status.setText("Pesquisando no YouTube…");}
 private void listen(){if(recognizing)return;recognizing=true;voice.setEnabled(false);if(!VoiceSearch.start(this,false,"Diga o nome da música ou artista para buscar no YouTube")){recognizing=false;voice.setEnabled(true);status.setText("Busca por voz indisponível. Digite no campo acima ou use o microfone do teclado.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=VoiceSearch.REQUEST)return;recognizing=false;voice.setEnabled(true);String phrase=VoiceSearch.result(result,data);if(result!=RESULT_OK){status.setText("Busca por voz cancelada. Você pode tentar novamente ou digitar.");return;}if(searchUrl(phrase).isEmpty()){status.setText("Nenhuma busca válida reconhecida. Tente novamente ou digite até 160 caracteres.");return;}query.setText(phrase);query.setSelection(query.length());search();}
 static String downloadUrl(String raw){try{return DownloadLinks.resolve(raw);}catch(Exception e){return "";}}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);protectionEnabled=getSharedPreferences(YouTubeProtection.PREF,0).getBoolean(YouTubeProtection.KEY,true);if(saved!=null&&allowed(saved.getString("url","")))lastUrl=saved.getString("url");String selected=YouTubeFavoritesData.canonical(getIntent().getStringExtra(YouTubeFavorites.EXTRA));if(saved==null&&!selected.isEmpty()){lastUrl=selected;pendingUrl=selected;}else if(saved!=null&&!YouTubeFavoritesData.canonical(lastUrl).isEmpty())pendingUrl=lastUrl;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,12),Ui.dp(this,8)+i.getSystemWindowInsetTop(),Ui.dp(this,12),Ui.dp(this,8)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar do YouTube");header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),-2));TextView title=Ui.text(this,"YouTube no Onda",22,Ui.TEXT);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button menu=Ui.menuButton(this,"Menu do YouTube",v->Ui.menu(this,v,new String[]{"Favoritos do YouTube","Salvar playlist desta página","Proteção de anúncios: "+(protectionEnabled?"ativa":"desligada"),"Recarregar página","Início do YouTube","Abrir no navegador","Central de downloads"},new String[]{"Favoritos do YouTube","Salvar playlist desta página","Proteção de anúncios","Recarregar página","Início do YouTube","Abrir YouTube no navegador","Central de downloads"},new Runnable[]{this::openFavorites,this::savePlaylist,this::protectionOptions,this::reloadPage,()->load("https://m.youtube.com/"),this::external,()->startActivity(new Intent(this,DownloadCenterActivity.class))}));header.addView(menu,new LinearLayout.LayoutParams(-2,-2));root.addView(header);DownloadTabs.add(this,root,true);
  LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);query=new EditText(this);query.setSingleLine(true);query.setTextSize(16);query.setHint("Música ou artista no YouTube");query.setContentDescription("Pesquisar no YouTube");query.setTextColor(Ui.TEXT);query.setHintTextColor(Ui.MUTED);query.setInputType(android.text.InputType.TYPE_CLASS_TEXT);query.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});query.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);query.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){search();return true;}return false;});if(saved!=null)query.setText(saved.getString("query",""));row.addView(query,new LinearLayout.LayoutParams(0,Ui.dp(this,52),1));Button submit=Ui.button(this,"⌕",v->search());submit.setTextSize(24);submit.setContentDescription("Buscar no YouTube");row.addView(submit,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,52)));voice=Ui.voiceButton(this,"Pesquisar YouTube por voz",v->listen());row.addView(voice,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,52)));root.addView(row);
  LinearLayout savedRow=new LinearLayout(this);favorite=Ui.button(this,"☆ Favoritar",v->toggleFavorite());favorite.setContentDescription("Favoritar vídeo ou playlist do YouTube");favorites=Ui.button(this,"Favoritos",v->openFavorites());favorites.setContentDescription("Abrir favoritos do YouTube");savedRow.addView(favorite,new LinearLayout.LayoutParams(0,-2,1));savedRow.addView(favorites,new LinearLayout.LayoutParams(0,-2,1));root.addView(savedRow);
  status=Ui.text(this,"Escolha um vídeo e consulte os formatos. A disponibilidade depende do YouTube.",12,Ui.MUTED);status.setContentDescription("Estado do YouTube no Onda");root.addView(status);holder=new LinearLayout(this);holder.setOrientation(LinearLayout.VERTICAL);root.addView(holder,new LinearLayout.LayoutParams(-1,0,1));formats=Ui.button(this,"Ver formatos para baixar",v->analyze());formats.setContentDescription("Consultar formatos do vídeo do YouTube");Ui.primary(formats);root.addView(formats,new LinearLayout.LayoutParams(-1,-2));formats.setEnabled(false);
 }
 @android.annotation.SuppressLint("SetJavaScriptEnabled") private void createBrowser(){
  try{web=new WebView(this);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setSupportMultipleWindows(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setContentDescription("Página oficial do YouTube");
   web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){return filterRequest(request);}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(allowed(url)){if(request.isForMainFrame()&&request.hasGesture())pendingUrl="";return false;}if(request.isForMainFrame())status.setText("Esse endereço abre fora da aba do YouTube. Use Abrir no navegador para continuar.");return true;}@Override public void doUpdateVisitedHistory(WebView view,String url,boolean reload){remember(view,url);}@Override public void onPageFinished(WebView view,String url){remember(view,url);if(visible&&view==web&&protectionEnabled&&allowed(url))view.evaluateJavascript(YouTubeProtection.cosmeticScript(),null);}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())status.setText("Não foi possível carregar o YouTube. Confira a conexão ou abra no navegador.");}});
   web.setWebChromeClient(new WebChromeClient(){@Override public void onReceivedTitle(WebView view,String text){if(view==web&&visible&&pendingUrl.isEmpty())updateFavorites();}});
   web.setDownloadListener((url,agent,disposition,mime,length)->status.setText("Abra o vídeo e toque em Ver formatos para baixar."));holder.addView(web,new LinearLayout.LayoutParams(-1,-1));web.resumeTimers();web.loadUrl(lastUrl);
  }catch(RuntimeException error){WebView failed=web;web=null;if(failed!=null){holder.removeView(failed);failed.stopLoading();failed.destroy();}status.setText("Atualize o Android System WebView ou abra o YouTube no navegador.");}
 }
 private WebResourceResponse filterRequest(WebResourceRequest request){if(!protectionEnabled||!YouTubeProtection.blocks(request.getUrl().toString(),request.isForMainFrame()))return null;blocked.incrementAndGet();return new WebResourceResponse("text/plain","UTF-8",204,"No Content",java.util.Collections.singletonMap("Cache-Control","no-store"),new java.io.ByteArrayInputStream(new byte[0]));}
 private void protectionOptions(){new AlertDialog.Builder(this).setTitle("Proteção de anúncios").setMessage((protectionEnabled?"Ativa":"Desligada")+" • "+blocked.get()+" solicitações publicitárias bloqueadas nesta sessão.\n\nRegras locais reforçadas para domínios de publicidade, endpoints de anúncios do YouTube e cartões patrocinados móveis/desktop. O contador mede solicitações bloqueadas, não anúncios removidos. Comerciais dentro dos vídeos ainda podem aparecer. Se uma página parar de funcionar, desative a proteção.\n\nAlterar recarrega a página e pode interromper o vídeo.").setNegativeButton("Fechar",null).setPositiveButton(protectionEnabled?"Desativar e recarregar":"Ativar e recarregar",(d,w)->setProtection(!protectionEnabled)).show();}
 private void setProtection(boolean enabled){protectionEnabled=enabled;getSharedPreferences(YouTubeProtection.PREF,0).edit().putBoolean(YouTubeProtection.KEY,enabled).apply();reloadPage();}
 private void reloadPage(){pendingUrl="";if(web!=null)web.reload();}
 static boolean matchesPending(String target,String actual){try{Uri wanted=Uri.parse(target),landed=Uri.parse(actual);if(!java.util.Objects.equals(wanted.getPath(),landed.getPath()))return false;if("/results".equals(wanted.getPath()))return java.util.Objects.equals(wanted.getQueryParameter("search_query"),landed.getQueryParameter("search_query"));if("/watch".equals(wanted.getPath()))return wanted.getQueryParameter("v")!=null&&java.util.Objects.equals(wanted.getQueryParameter("v"),landed.getQueryParameter("v"));if("/playlist".equals(wanted.getPath()))return wanted.getQueryParameter("list")!=null&&java.util.Objects.equals(wanted.getQueryParameter("list"),landed.getQueryParameter("list"));return "/".equals(wanted.getPath());}catch(Exception e){return false;}}
 private void remember(WebView view,String url){if(view!=web||!visible||!allowed(url)||!java.util.Objects.equals(view.getUrl(),url))return;if(!pendingUrl.isEmpty()&&!matchesPending(pendingUrl,url))return;pendingUrl="";lastUrl=url;updateFavorites();formats.setEnabled(!downloadUrl(url).isEmpty());status.setText(downloadUrl(url).isEmpty()?"Escolha um vídeo ou playlist para consultar os formatos.":"Vídeo selecionado • consulte áudio ou vídeo disponíveis.");}
 private void load(String url){if(!allowed(url))return;lastUrl=url;pendingUrl=url;formats.setEnabled(false);updateFavorites();if(web!=null)web.loadUrl(url);}
 private void updateFavorites(){if(favorite==null)return;YouTubeFavoritesData data=YouTubeFavorites.read(this);String url=YouTubeFavoritesData.canonical(lastUrl);boolean saved=data.find(url)!=null;favorite.setText(saved?"★ Favoritado":"☆ Favoritar");favorite.setContentDescription(saved?"Remover página dos favoritos do YouTube":"Favoritar vídeo ou playlist do YouTube");favorite.setEnabled(data.writable&&!url.isEmpty()&&pendingUrl.isEmpty());favorites.setText("Favoritos ("+data.items.size()+")");Ui.chip(favorite,saved);}
 private void openFavorites(){startActivity(new Intent(this,YouTubeFavoritesActivity.class));}
 private void toggleFavorite(){String url=YouTubeFavoritesData.canonical(lastUrl);if(url.isEmpty()||!pendingUrl.isEmpty())return;if(YouTubeFavorites.read(this).find(url)!=null){YouTubeFavorites.remove(this,url);updateFavorites();status.setText("Removido dos favoritos do YouTube.");}else saveFavorite(url,null);}
 private void savePlaylist(){String url=YouTubeFavoritesData.playlist(lastUrl);if(url.isEmpty()||!pendingUrl.isEmpty()){status.setText("Abra uma playlist ou um vídeo pertencente a uma playlist antes de salvar.");return;}saveFavorite(url,lastUrl.contains("/playlist?")?null:"Playlist do YouTube");}
 private void saveFavorite(String url,String suggested){YouTubeFavoritesData data=YouTubeFavorites.read(this);if(!data.writable){status.setText("Os favoritos foram preservados: formato desconhecido ou dados inválidos.");return;}YouTubeFavoritesData.Item previous=data.find(url);if(previous==null&&data.items.size()>=YouTubeFavoritesData.MAX){status.setText("Limite de 200 favoritos. Remova um item para salvar outro.");return;}String name=previous==null?suggested:previous.title;if(name==null&&web!=null&&java.util.Objects.equals(web.getUrl(),lastUrl))name=web.getTitle();if(name!=null)name=name.replaceFirst("(?i)\\s*[-–—|]\\s*YouTube\\s*$","").trim();if(name==null||name.isEmpty()||name.equalsIgnoreCase("YouTube"))name=url.contains("/playlist?")?"Playlist do YouTube":"Vídeo do YouTube";EditText input=new EditText(this);input.setSingleLine(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});input.setText(YouTubeFavoritesData.title(name));input.setContentDescription("Nome do favorito do YouTube");if(saveDialog!=null)saveDialog.dismiss();saveDialog=new AlertDialog.Builder(this).setTitle("Salvar nos favoritos do Onda").setMessage(url).setView(input).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();saveDialog.setOnShowListener(d->saveDialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String title=YouTubeFavoritesData.title(input.getText().toString());if(title.isEmpty()){input.setError("Digite um nome");return;}if(!YouTubeFavorites.save(this,url,title)){input.setError("Não foi possível salvar; verifique o limite ou os dados existentes");return;}saveDialog.dismiss();updateFavorites();status.setText("Salvo nos favoritos do YouTube deste celular.");}));saveDialog.show();}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);String url=YouTubeFavoritesData.canonical(intent.getStringExtra(YouTubeFavorites.EXTRA));if(!url.isEmpty())load(url);}
 private void analyze(){String url=downloadUrl(web==null?lastUrl:web.getUrl());if(url.isEmpty()){status.setText("Abra um vídeo ou playlist antes de consultar os formatos.");return;}startActivity(new Intent(this,DownloadsActivity.class).putExtra("analyze_link",url).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));}
 private void external(){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(lastUrl)));}catch(ActivityNotFoundException error){status.setText("Nenhum navegador disponível.");}}
 @Override protected void onResume(){super.onResume();visible=true;if(web==null&&!YouTubeFavoritesData.canonical(lastUrl).isEmpty())pendingUrl=lastUrl;updateFavorites();if(web==null)createBrowser();else{web.onResume();web.resumeTimers();}}
 @Override protected void onPause(){visible=false;if(web!=null){web.evaluateJavascript("document.querySelectorAll('video,audio').forEach(function(m){m.pause();});",null);web.onPause();web.pauseTimers();}super.onPause();}
 @Override protected void onStop(){if(web!=null){WebView old=web;web=null;holder.removeView(old);old.stopLoading();old.destroy();}super.onStop();}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack()){pendingUrl="";web.goBack();}else super.onBackPressed();}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("url",lastUrl);state.putString("query",query.getText().toString());super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(web!=null){holder.removeView(web);web.destroy();web=null;}if(saveDialog!=null)saveDialog.dismiss();super.onDestroy();}
}
